  { conversionMSOTEventsActionUnderscoretimestamps :: Maybe [Int64] -- ^ Timestamp(s) when the ad action(s) happened. Unix timestamp in seconds.
  , conversionMSOTEventsAdUnderscoregroupUnderscoreid :: Text -- ^ The ID of the ad group that was attributed to the conversion event.
  , conversionMSOTEventsAttributionUnderscoremodel :: Maybe Text -- ^ The attribution model used to attribute the conversion event.
  , conversionMSOTEventsAttributionUnderscorescope :: Text -- ^ Ad event type.
  , conversionMSOTEventsAttributionUnderscorescore :: Maybe Double -- ^ Credit given to the attributed ad actions. Allowed values are > 0 and <= 1.
  , conversionMSOTEventsCampaignUnderscoreid :: Maybe Text -- ^ The ID of the campaign that was attributed to the conversion event.
  , conversionMSOTEventsCurrency :: Maybe Currency -- ^ 
  , conversionMSOTEventsEventUnderscoreid :: Text -- ^ A unique id string that identifies this event. If you are already sending us events through Conversions API, then this id should match the event_id sent through Conversions API.
  , conversionMSOTEventsEventUnderscorename :: Text -- ^ Type of user event.
  , conversionMSOTEventsEventUnderscoretimestamp :: Int64 -- ^ The time when the event occurred. Unix timestamp in seconds.
  , conversionMSOTEventsTotalUnderscoreeventUnderscoretouchpoints :: Maybe Int -- ^ Total number of ad events including other non-Pinterest ad platforms.
  , conversionMSOTEventsTotalUnderscoreevents :: Maybe Int -- ^ Total number of conversion events that are reported in one API call. <p>If you are sending one API request for one attributed conversion event then this value should be 1.</p> <p>If you are sending multiple attributed conversion events in one API request then this value should be the total number of attributed conversion events in the request.</p>
  , conversionMSOTEventsValue :: Maybe Double -- ^ Order value of the conversion event. Required if <code>event_name</code> is 'add_to_cart' or 'checkout'.
  } deriving (Show, Eq, Generic)

